<h2>Estimate break-even units and revenue</h2><p class="lead">Use fixed cost, selling price and variable cost per unit to calculate a simple accounting break-even point.</p><div class="form-grid"><div class="field"><label for="fixed">Fixed costs</label><input id="fixed" type="number" min="0" step="0.01" value="50000"></div><div class="field"><label for="price">Selling price per unit</label><input id="price" type="number" min="0" step="0.01" value="120"></div><div class="field full"><label for="variable">Variable cost per unit</label><input id="variable" type="number" min="0" step="0.01" value="70"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc">Calculate</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Contribution per unit</span><strong id="contribution">—</strong></div><div class="metric"><span>Break-even units</span><strong id="units">—</strong></div><div class="metric"><span>Break-even revenue</span><strong id="revenue">—</strong></div></div><div id="warning"></div></div>
<script>(()=>{const $=i=>document.getElementById(i),n=i=>parseFloat($(i).value)||0,m=x=>'$'+x.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});function go(){const f=n('fixed'),p=n('price'),v=n('variable'),c=p-v;$('contribution').textContent=m(c);if(c<=0){$('units').textContent='Not reachable';$('revenue').textContent='Not reachable';$('warning').innerHTML='<div class="notice"><strong class="danger">Selling price must exceed variable cost</strong><br>There is no positive per-unit contribution to absorb fixed costs.</div>';return}const exact=f/c,units=Math.ceil(exact);$('units').textContent=units.toLocaleString();$('revenue').textContent=m(units*p);$('warning').innerHTML=''}document.querySelectorAll('input').forEach(x=>x.addEventListener('input',go));$('calc').onclick=go;go()})();</script>
